// Checks for glob-match, dotenv, query-string, mime-types, data-uri, iso-week, topo-sort, link-header,
// content-disposition and cache-control. Vector literals are generated by a script from the shared wave 10 vectors.json
// (JSON null = nil; hex strings are byte inputs). Results are serialized and compared as Unicode scalars because Swift
// String equality treats canonically equivalent text as equal.
import GenlibSwift

private func scalars(_ s: String) -> [UInt32] { s.unicodeScalars.map(\.value) }
private func same(_ c: inout Checks, _ name: String, _ expected: String?, _ actual: () throws -> String?) {
    do {
        let v = try actual()
        let ok = v.map(scalars) == expected.map(scalars)
        if !ok { print("  expected <\(expected ?? "nil")> got <\(v ?? "nil")>") }
        c.check(name, ok)
    } catch {
        print("  unexpected error: \(error)")
        c.check(name, false)
    }
}
private func kv(_ ps: [(name: String, value: String)]) -> String { ps.map { "\($0.name)\u{241F}\($0.value)" }.joined(separator: "\u{241E}") }
private func kv2(_ ps: [(key: String, value: String)]) -> String { ps.map { "\($0.key)\u{241F}\($0.value)" }.joined(separator: "\u{241E}") }
private func join(_ xs: [String]) -> String { xs.joined(separator: "\u{241E}") }
private func hexOf(_ b: [UInt8]) -> String { b.map { String($0, radix: 16).count == 1 ? "0" + String($0, radix: 16) : String($0, radix: 16) }.joined() }
private func hex(_ h: String) -> [UInt8] {
    let a = Array(h.utf8)
    return stride(from: 0, to: a.count, by: 2).map { UInt8(String(decoding: a[$0..<$0 + 2], as: UTF8.self), radix: 16)! }
}
private func links(_ ls: [Link]) -> String { ls.map { "\($0.uri)\u{241D}\(kv($0.params))" }.joined(separator: "\u{241C}") }
private func cc(_ ds: [(name: String, value: CacheControl.Value)]) -> String {
    ds.map { d -> String in
        switch d.value {
        case .flag: return "\(d.name)\u{241F}T"
        case .seconds(let v): return "\(d.name)\u{241F}I:\(v)"
        case .text(let t): return "\(d.name)\u{241F}S:\(t)"
        }
    }.joined(separator: "\u{241E}")
}
private func tuple3(_ t: (Int, Int, Int)) -> String { "\(t.0)-\(t.1)-\(t.2)" }

func runWave10Checks(_ c: inout Checks) {
    c.eq("glob match 0 *.js a.js", true, try GlobMatch.matches("*.js", "a.js", dot: false))
    c.eq("glob match 1 *.js a/b.js", false, try GlobMatch.matches("*.js", "a/b.js", dot: false))
    c.eq("glob match 2 **/*.js a/b/c.js", true, try GlobMatch.matches("**/*.js", "a/b/c.js", dot: false))
    c.eq("glob match 3 **/*.js c.js", true, try GlobMatch.matches("**/*.js", "c.js", dot: false))
    c.eq("glob match 4 src/** src", true, try GlobMatch.matches("src/**", "src", dot: false))
    c.eq("glob match 5 src/** src/a/b.ts", true, try GlobMatch.matches("src/**", "src/a/b.ts", dot: false))
    c.eq("glob match 6 src/**/test/*.py src/test/x.py", true, try GlobMatch.matches("src/**/test/*.py", "src/test/x.py", dot: false))
    c.eq("glob match 7 src/**/test/*.py src/a/b/test/x.py", true, try GlobMatch.matches("src/**/test/*.py", "src/a/b/test/x.py", dot: false))
    c.eq("glob match 8 a?c abc", true, try GlobMatch.matches("a?c", "abc", dot: false))
    c.eq("glob match 9 a?c a/c", false, try GlobMatch.matches("a?c", "a/c", dot: false))
    c.eq("glob match 10 [a-c]x bx", true, try GlobMatch.matches("[a-c]x", "bx", dot: false))
    c.eq("glob match 11 [!a-c]x bx", false, try GlobMatch.matches("[!a-c]x", "bx", dot: false))
    c.eq("glob match 12 [!a-c]x dx", true, try GlobMatch.matches("[!a-c]x", "dx", dot: false))
    c.eq("glob match 13 [^0-9] x", true, try GlobMatch.matches("[^0-9]", "x", dot: false))
    c.eq("glob match 14 []a] a", true, try GlobMatch.matches("[]a]", "a", dot: false))
    c.eq("glob match 15 []a] ]", true, try GlobMatch.matches("[]a]", "]", dot: false))
    c.eq("glob match 16 *.{js,ts} x.ts", true, try GlobMatch.matches("*.{js,ts}", "x.ts", dot: false))
    c.eq("glob match 17 *.{js,ts} x.tsx", false, try GlobMatch.matches("*.{js,ts}", "x.tsx", dot: false))
    c.eq("glob match 18 {src,lib}/**/*.go lib/x/y.go", true, try GlobMatch.matches("{src,lib}/**/*.go", "lib/x/y.go", dot: false))
    c.eq("glob match 19 .* .env", true, try GlobMatch.matches(".*", ".env", dot: false))
    c.eq("glob match 20 * .env", false, try GlobMatch.matches("*", ".env", dot: false))
    c.eq("glob match 21 * .env", true, try GlobMatch.matches("*", ".env", dot: true))
    c.eq("glob match 22 **/x .git/x", false, try GlobMatch.matches("**/x", ".git/x", dot: false))
    c.eq("glob match 23 **/x .git/x", true, try GlobMatch.matches("**/x", ".git/x", dot: true))
    c.eq("glob match 24 a*b a*b", true, try GlobMatch.matches("a\\*b", "a*b", dot: false))
    c.eq("glob match 25 a*b axb", false, try GlobMatch.matches("a\\*b", "axb", dot: false))
    c.eq("glob match 26 * ", true, try GlobMatch.matches("*", "", dot: false))
    c.eq("glob match 27 ** a/b/c", true, try GlobMatch.matches("**", "a/b/c", dot: false))
    c.eq("glob match 28 a/**/b a/b", true, try GlobMatch.matches("a/**/b", "a/b", dot: false))
    c.eq("glob match 29 a/**/b a/x/y/b", true, try GlobMatch.matches("a/**/b", "a/x/y/b", dot: false))
    c.eq("glob match 30 *.txt notes.TXT", false, try GlobMatch.matches("*.txt", "notes.TXT", dot: false))
    c.eq("glob match 31 [a-z]*.md Readme.md", false, try GlobMatch.matches("[a-z]*.md", "Readme.md", dot: false))
    c.eq("glob match 32 docs/* docs/a/b", false, try GlobMatch.matches("docs/*", "docs/a/b", dot: false))
    c.eq("glob match 33 ? u00e9", true, try GlobMatch.matches("?", "\u{E9}", dot: false))
    c.throwsError("glob invalid 0 [abc", { _ = try GlobMatch.matches("[abc", "x") }, where: { $0 is GlobMatchError })
    c.throwsError("glob invalid 1 {a,b", { _ = try GlobMatch.matches("{a,b", "x") }, where: { $0 is GlobMatchError })
    c.throwsError("glob invalid 2 a{b{c}}", { _ = try GlobMatch.matches("a{b{c}}", "x") }, where: { $0 is GlobMatchError })
    c.throwsError("glob invalid 3 ", { _ = try GlobMatch.matches("", "x") }, where: { $0 is GlobMatchError })
    c.throwsError("glob invalid 4 x", { _ = try GlobMatch.matches("x\\", "x") }, where: { $0 is GlobMatchError })
    same(&c, "glob filter", "a.js\u{241E}b/c.js") { join(try GlobMatch.filter("**/*.js", ["a.js", "b/c.js", "d.ts", ".h/e.js"])) }
    same(&c, "dotenv parse 0 A=1nB=twon", "A\u{241F}1\u{241E}B\u{241F}two") { kv2(try Dotenv.parse("A=1\nB=two\n")) }
    same(&c, "dotenv parse 1 # cnnexport KEY = value with s...", "KEY\u{241F}value with spaces") { kv2(try Dotenv.parse("# c\n\nexport KEY = value with spaces  # comment\n")) }
    same(&c, "dotenv parse 2 Q=anbtc  $HOMEn", "Q\u{241F}a\nb\t\"c\" \\ $HOME") { kv2(try Dotenv.parse("Q=\"a\\nb\\t\\\"c\\\" \\\\ \\$HOME\"\n")) }
    same(&c, "dotenv parse 3 S='raw ${X} n'n", "S\u{241F}raw ${X} \\n") { kv2(try Dotenv.parse("S='raw ${X} \\n'\n")) }
    same(&c, "dotenv parse 4 M=line1nline2nN=aftern", "M\u{241F}line1\nline2\u{241E}N\u{241F}after") { kv2(try Dotenv.parse("M=\"line1\nline2\"\nN=after\n")) }
    same(&c, "dotenv parse 5 E=nF= n", "E\u{241F}\u{241E}F\u{241F}") { kv2(try Dotenv.parse("E=\nF= \n")) }
    same(&c, "dotenv parse 6 DUP=1nDUP=2n", "DUP\u{241F}2") { kv2(try Dotenv.parse("DUP=1\nDUP=2\n")) }
    same(&c, "dotenv parse 7 URL=https://x.test/#fragn", "URL\u{241F}https://x.test/#frag") { kv2(try Dotenv.parse("URL=https://x.test/#frag\n")) }
    same(&c, "dotenv parse 8 H=a#bn", "H\u{241F}a#b") { kv2(try Dotenv.parse("H=a#b\n")) }
    same(&c, "dotenv parse 9 K.x_y=1n", "K.x_y\u{241F}1") { kv2(try Dotenv.parse("K.x_y=1\n")) }
    same(&c, "dotenv parse 10 W=x # trailing okn", "W\u{241F}x") { kv2(try Dotenv.parse("W=\"x\" # trailing ok\n")) }
    same(&c, "dotenv parse 11 CRLF=1rnNEXT=2rn", "CRLF\u{241F}1\u{241E}NEXT\u{241F}2") { kv2(try Dotenv.parse("CRLF=1\r\nNEXT=2\r\n")) }
    same(&c, "dotenv expand 0 A=1nB=${A}-xn", "A\u{241F}1\u{241E}B\u{241F}1-x") { kv2(try Dotenv.parse("A=1\nB=${A}-x\n", expand: true, vars: [:])) }
    same(&c, "dotenv expand 1 B=${A}nA=1n", "B\u{241F}env\u{241E}A\u{241F}1") { kv2(try Dotenv.parse("B=${A}\nA=1\n", expand: true, vars: ["A": "env"])) }
    same(&c, "dotenv expand 2 P=${MISSING:-fallback}nQ=${EMP...", "P\u{241F}fallback\u{241E}Q\u{241F}d") { kv2(try Dotenv.parse("P=${MISSING:-fallback}\nQ=${EMPTY:-d}\n", expand: true, vars: ["EMPTY": ""])) }
    same(&c, "dotenv expand 3 S='${A}'nT=${A}nU=${A}n", "S\u{241F}${A}\u{241E}T\u{241F}v\u{241E}U\u{241F}${A}") { kv2(try Dotenv.parse("S='${A}'\nT=\"${A}\"\nU=\"\\${A}\"\n", expand: true, vars: ["A": "v"])) }
    c.throwsError("dotenv invalid 0 NOEQUALSn", { _ = try Dotenv.parse("NOEQUALS\n") }, where: { if case DotenvError.invalidLine(let n, _) = $0 { return n >= 1 }; return false })
    c.throwsError("dotenv invalid 1 1BAD=xn", { _ = try Dotenv.parse("1BAD=x\n") }, where: { if case DotenvError.invalidLine(let n, _) = $0 { return n >= 1 }; return false })
    c.throwsError("dotenv invalid 2 A='unterminatedn", { _ = try Dotenv.parse("A='unterminated\n") }, where: { if case DotenvError.invalidLine(let n, _) = $0 { return n >= 1 }; return false })
    c.throwsError("dotenv invalid 3 A=never closednB=1n", { _ = try Dotenv.parse("A=\"never closed\nB=1\n") }, where: { if case DotenvError.invalidLine(let n, _) = $0 { return n >= 1 }; return false })
    c.throwsError("dotenv invalid 4 A=x junkn", { _ = try Dotenv.parse("A=\"x\" junk\n") }, where: { if case DotenvError.invalidLine(let n, _) = $0 { return n >= 1 }; return false })
    c.throwsError("dotenv invalid 5 -K=vn", { _ = try Dotenv.parse("-K=v\n") }, where: { if case DotenvError.invalidLine(let n, _) = $0 { return n >= 1 }; return false })
    same(&c, "query parse 0 a=1&b=2", "a\u{241F}1\u{241E}b\u{241F}2") { kv(QueryString.parse("a=1&b=2")) }
    same(&c, "query parse 1 ?a=1&a=2", "a\u{241F}1\u{241E}a\u{241F}2") { kv(QueryString.parse("?a=1&a=2")) }
    same(&c, "query parse 2 x=a+b%20c", "x\u{241F}a b c") { kv(QueryString.parse("x=a+b%20c")) }
    same(&c, "query parse 3 e=%E2%82%AC", "e\u{241F}\u{20AC}") { kv(QueryString.parse("e=%E2%82%AC")) }
    same(&c, "query parse 4 bad=%zz&ok=1", "bad\u{241F}%zz\u{241E}ok\u{241F}1") { kv(QueryString.parse("bad=%zz&ok=1")) }
    same(&c, "query parse 5 %", "%\u{241F}") { kv(QueryString.parse("%")) }
    same(&c, "query parse 6 &&a&&", "a\u{241F}") { kv(QueryString.parse("&&a&&")) }
    same(&c, "query parse 7 k=v=w", "k\u{241F}v=w") { kv(QueryString.parse("k=v=w")) }
    same(&c, "query parse 8 =v", "\u{241F}v") { kv(QueryString.parse("=v")) }
    same(&c, "query parse 9 emoji=%F0%9F%98%80", "emoji\u{241F}\u{1F600}") { kv(QueryString.parse("emoji=%F0%9F%98%80")) }
    same(&c, "query parse 10 invalid=%FF", "invalid\u{241F}\u{FFFD}") { kv(QueryString.parse("invalid=%FF")) }
    same(&c, "query parse 11 plus=%2B", "plus\u{241F}+") { kv(QueryString.parse("plus=%2B")) }
    same(&c, "query stringify 0", "a=1&b=x+y") { QueryString.stringify([("a", "1"), ("b", "x y")]) }
    same(&c, "query stringify 1", "q=a%26b%3Dc&e=%E2%82%AC") { QueryString.stringify([("q", "a&b=c"), ("e", "\u{20AC}")]) }
    same(&c, "query stringify 2", "*-._=%7E%21%27%28%29") { QueryString.stringify([("*-._", "~!'()")]) }
    same(&c, "query stringify 3", "k=&=v") { QueryString.stringify([("k", ""), ("", "v")]) }
    same(&c, "query getAll 0", "1\u{241E}3") { join(QueryString.getAll(QueryString.parse("a=1&b=2&a=3"), "a")) }
    same(&c, "mime typeFor 0 index.html", "text/html") { MimeTypes.typeFor("index.html") }
    same(&c, "mime typeFor 1 APP.JS", "text/javascript") { MimeTypes.typeFor("APP.JS") }
    same(&c, "mime typeFor 2 data.json", "application/json") { MimeTypes.typeFor("data.json") }
    same(&c, "mime typeFor 3 photo.JPG", "image/jpeg") { MimeTypes.typeFor("photo.JPG") }
    same(&c, "mime typeFor 4 x.tar.gz", "application/gzip") { MimeTypes.typeFor("x.tar.gz") }
    same(&c, "mime typeFor 5 video.webm", "video/webm") { MimeTypes.typeFor("video.webm") }
    same(&c, "mime typeFor 6 font.woff2", "font/woff2") { MimeTypes.typeFor("font.woff2") }
    same(&c, "mime typeFor 7 doc.docx", "application/vnd.openxmlformats-officedocument.wordprocessingml.document") { MimeTypes.typeFor("doc.docx") }
    same(&c, "mime typeFor 8 noext", nil) { MimeTypes.typeFor("noext") }
    same(&c, "mime typeFor 9 json", "application/json") { MimeTypes.typeFor("json") }
    same(&c, "mime typeFor 10 .png", "image/png") { MimeTypes.typeFor(".png") }
    same(&c, "mime typeFor 11 a.unknown", nil) { MimeTypes.typeFor("a.unknown") }
    same(&c, "mime typeFor 12 style.css", "text/css") { MimeTypes.typeFor("style.css") }
    same(&c, "mime typeFor 13 feed.xml", "application/xml") { MimeTypes.typeFor("feed.xml") }
    same(&c, "mime typeFor 14 pic.svg", "image/svg+xml") { MimeTypes.typeFor("pic.svg") }
