    same(&c, "data uri parse 2 data:text/html;charset=utf-8,%...", "text/html|charset\u{241F}utf-8|raw|3c68313e48693c2f68313e") { let r = try DataUri.parse("data:text/html;charset=utf-8,%3Ch1%3EHi%3C%2Fh1%3E"); return "\(r.mime)|\(kv(r.params))|\(r.base64 ? "b64" : "raw")|\(hexOf(r.data))" }
