    same(&c, "data uri parse 6 data:application/json,%7B%22a%...", "application/json||raw|7b2261223a317d") { let r = try DataUri.parse("data:application/json,%7B%22a%22%3A1%7D"); return "\(r.mime)|\(kv(r.params))|\(r.base64 ? "b64" : "raw")|\(hexOf(r.data))" }
